import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"日志审计","description":"","frontmatter":{},"headers":[],"relativePath":"backend/logging.md","filePath":"backend/logging.md","lastUpdated":1794049926000}`),a={name:`backend/logging.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="日志审计" tabindex="-1">日志审计 <a class="header-anchor" href="#日志审计" aria-label="Permalink to “日志审计”">​</a></h1><p>本页说明八类日志的来源与内容、链路追踪、写入方式与保留清理，适用于后端开发者与运维、审计人员。</p><p>Auditing 包（Tier 2）负责日志的写入队列与查询面。八类日志里，七类是 Auditing 自己的按月分表，操作日志是框架的操作审计。日志页都是只读的，权限码只有 <code>read</code>，平台与租户两侧都有。</p><h2 id="八类日志" tabindex="-1">八类日志 <a class="header-anchor" href="#八类日志" aria-label="Permalink to “八类日志”">​</a></h2><table tabindex="0"><thead><tr><th>日志</th><th>表（按月分表，表名里的日期是当月 1 日）</th><th>写入方</th><th>操作 / 权限码</th></tr></thead><tbody><tr><td>访问日志</td><td><code>sys_access_log_{year}{month}{day}</code></td><td><code>AuditLogMiddleware</code>：每次调用的协议、目标、状态、耗时、主体、客户端</td><td><code>access-logs.*</code> / <code>auditing.access-logs.read</code></td></tr><tr><td>操作日志</td><td><code>audit_record</code>（框架 <code>Auditing.Database</code>）</td><td>框架 <code>AuditMiddleware</code>，标了 <code>audited</code> 的操作才记</td><td><code>operation-logs.*</code> / <code>auditing.operation-logs.read</code></td></tr><tr><td>登录日志</td><td><code>sys_login_log_{year}{month}{day}</code></td><td>Identity 在调用里登记，成败都记</td><td><code>login-logs.*</code> / <code>auditing.login-logs.read</code></td></tr><tr><td>异常日志</td><td><code>sys_exception_log_{year}{month}{day}</code></td><td><code>AuditLogMiddleware</code>：未预期的失败与异常</td><td><code>exception-logs.*</code> / <code>auditing.exception-logs.read</code></td></tr><tr><td>数据变更日志</td><td><code>sys_diff_log_{year}{month}{day}</code></td><td>SqlSugar 差异事件（<code>OnDiffLogEvent</code>），按调用缓冲、成功才落库</td><td><code>diff-logs.*</code> / <code>auditing.diff-logs.read</code></td></tr><tr><td>权限变更日志</td><td><code>sys_permission_change_log_{year}{month}{day}</code></td><td>Access / Tenancy 在调用里登记，成功才落库</td><td><code>permission-change-logs.*</code> / <code>auditing.permission-change-logs.read</code></td></tr><tr><td>条件命中</td><td><code>sys_condition_hit_{year}{month}{day}</code></td><td>访问策略与权限条件，与调用成败无关</td><td><code>condition-hits.*</code> / <code>auditing.condition-hits.read</code></td></tr><tr><td>开放接口日志</td><td><code>sys_open_api_log_{year}{month}{day}</code></td><td>OpenPlatform 的验签中间件，每次调用无论成败</td><td><code>open-api-logs.*</code> / <code>auditing.open-api-logs.read</code></td></tr></tbody></table><p>每类都是 <code>list</code>（<code>POST /api/&lt;资源&gt;:list</code>，分页筛选）与 <code>get</code>（<code>GET /api/&lt;资源&gt;/{id}</code>）两个操作。</p><p>个人中心另有两个自助操作（只要求登录，只看本人）：<code>my-login-logs.list</code>（本人的登录日志，每页 1–50 条）与 <code>my-activity.summary</code>（今天、本周、本月的登录、访问、操作次数与在线时长，以及近一年的每日活跃）。</p><h3 id="隔离" tabindex="-1">隔离 <a class="header-anchor" href="#隔离" aria-label="Permalink to “隔离”">​</a></h3><p>日志是租户库实体，严格按上下文隔离：平台主体看平台一侧（平台主体、匿名调用、找不到租户的登录都记在 <code>platform</code>），租户主体看本租户。要看某个租户的日志，先切换到该租户。</p><h3 id="各类的内容" tabindex="-1">各类的内容 <a class="header-anchor" href="#各类的内容" aria-label="Permalink to “各类的内容”">​</a></h3><ul><li>操作日志：操作 ID、本地化的描述（取操作的 <code>.title</code>，按调用方语言）、结果与错误码、耗时、登录名与会话，以及客户端 IP、浏览器、系统、设备、归属地（经 <code>IIpRegionResolver</code> 离线库）。</li><li>登录日志：事件 <code>Login</code>、<code>Refresh</code>、<code>Logout</code>、<code>SwitchTenant</code>、<code>ImpersonationStart</code> / <code>ImpersonationStop</code>、<code>ChangePassword</code>、<code>TwoFactorChallenge</code> / <code>TwoFactorEnable</code> / <code>TwoFactorDisable</code> / <code>TwoFactorReset</code>、<code>RoleActivation</code>；验证码错误、节流拒绝与第二步码错都作为失败的登录带错误码记下。</li><li>数据变更日志：类型 <code>Insert</code>、<code>Update</code>、<code>Delete</code>、<code>Restore</code>（软删除标记由真变假）。只记全审计实体（<code>AppAuditedEntity</code> 及其租户变体），实体类标 <code>[DiffLogIgnored]</code> 即不记（会话、个人偏好、账号安全、API 凭证、发送记录、OAuth 令牌等）；修改按主键配对前后值，列名含 password / hash / secret / token / salt 的值打码；只动了时间戳、操作人、并发戳的修改不记；作业与种子的写入不记。</li><li>权限变更日志：<code>RoleGrant</code> / <code>RoleRevoke</code> / <code>RoleDeny</code>、<code>RoleAssign</code> / <code>RoleUnassign</code> / <code>RoleAssignmentWindow</code>、<code>RoleDataScope</code>、<code>RoleDelete</code>、<code>RoleInheritance</code>、<code>UserGrant</code> / <code>UserDeny</code> / <code>UserRevoke</code>、<code>UserDataScope</code>、<code>Delegation</code>、<code>FieldSecurity</code>、<code>ConditionChange</code>、<code>ConstraintViolation</code>、<code>EditionPermissions</code>、<code>TenantEdition</code>、<code>TenantOwner</code>。</li><li>条件命中：来源（访问策略 / 权限条件）、时机（认证前、认证后、登录、授权）、动作与是否拦截、请求属性快照。</li></ul><h2 id="链路追踪" tabindex="-1">链路追踪 <a class="header-anchor" href="#链路追踪" aria-label="Permalink to “链路追踪”">​</a></h2><p><code>traces.timeline</code>（<code>GET</code>，<code>auditing.traces.read</code>）：按一个维度把多类日志串成时间线。</p><table tabindex="0"><thead><tr><th>维度</th><th>值</th></tr></thead><tbody><tr><td>trace-id</td><td>一次请求的全部日志</td></tr><tr><td>用户 / 登录名 / 会话 / 客户端地址</td><td>某人、某端在一段时间里的行为</td></tr></tbody></table><p>可限定时间范围、日志类型与每类条数（1–500，缺省 200，超出即标截断）。操作日志没有会话与地址列，按其他日志里出现过的 trace-id 反查。客户端每个请求自带 <code>traceparent</code>，失败响应的 <code>traceId</code> 与之对应，排障时直接拿它查。前端的链路页另有流向图与时间分布。</p><h2 id="写入" tabindex="-1">写入 <a class="header-anchor" href="#写入" aria-label="Permalink to “写入”">​</a></h2><ul><li>七类分表日志走有界队列（<code>BasicApp:Auditing:QueueCapacity</code> / <code>BatchSize</code> / <code>FlushIntervalSeconds</code>），后台按租户批量落库，队列满了丢弃新到的并计数；共库与平台一侧直接写，独立库租户先经 <code>TenantShardScope</code> 绑定分片。</li><li>写日志不改变调用结果。</li><li>访问日志可整体关闭或按操作 ID 排除（<code>BasicApp:Auditing:AccessLog:Enabled</code> / <code>Exclude</code>），异常、登录与变更日志不受影响。</li><li>普通端点（上传、下载、头像）由宿主的端点过滤器登记端点身份与实际状态码，按 <code>files.upload</code> 这类名字记访问日志与数据变更；授权阶段就被拒绝的调用按框架带进上下文的端点名记，状态码按错误类别推出。</li></ul><h2 id="保留清理" tabindex="-1">保留清理 <a class="header-anchor" href="#保留清理" aria-label="Permalink to “保留清理”">​</a></h2><p>作业 <code>auditing.retention</code>（<code>BasicApp:Auditing:RetentionCron</code>，缺省每天 03:00 UTC）读平台的系统参数 <code>auditing.retention-days</code>（1–3650；没建即 <code>BasicApp:Auditing:DefaultRetentionDays</code>，180 天；不合法即失败，不按错误的保留期删数据）。七类分表日志按平台与每个租户逐批删除，再单独清一遍操作审计表；一处失败只记日志、计入失败，不影响其他。</p><h2 id="页面" tabindex="-1">页面 <a class="header-anchor" href="#页面" aria-label="Permalink to “页面”">​</a></h2><p><code>src/modules/auditing</code>：链路追踪与八个日志页（SchemaPage），详情抽屉、追踪跳转、时间线与流向图。开放接口日志挂在「集成中心 › 开放接口」目录下，其余在「系统管理 › 系统日志」下。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./request-lifecycle">请求生命周期</a> · <a href="./health-observability">健康与可观测性</a> · <a href="./access-policy">访问策略与权限条件</a></li></ul>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};